with a as(select * from public.authors where open_library_id=any(array['OL24522A','OL170469A']::text[])),w as(select * from public.works where open_library_id=any(array['OL20600W','OL15450151W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780721417523','9780679600992','9789027491251','9789027491503']::text[]) or open_library_edition_id=any(array['OL24354314M','OL7862297M','OL24354315M','OL7699589M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987115001 and 987115999),'editions',(select count(*) from public.editions where id between 987215001 and 987215999),'authors',(select count(*) from public.authors where id between 987315001 and 987315999))) as preflight;
